-- Phase 1: additive D1 schema. Firestore remains authoritative until a later read cutover.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS businesses (id TEXT PRIMARY KEY, name TEXT NOT NULL, vertical TEXT NOT NULL CHECK(vertical IN ('eats','motos','cabs')), products_json TEXT NOT NULL DEFAULT '[]', active INTEGER NOT NULL, whatsapp_phone_number_id TEXT, data_json TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS whatsapp_accounts (id TEXT PRIMARY KEY, business_id TEXT NOT NULL REFERENCES businesses(id), phone_number_id TEXT, waba_id TEXT, status TEXT NOT NULL, data_json TEXT NOT NULL DEFAULT '{}', updated_at INTEGER NOT NULL, UNIQUE(phone_number_id));
CREATE TABLE IF NOT EXISTS whatsapp_phone_mappings (phone_number_id TEXT PRIMARY KEY, business_id TEXT NOT NULL REFERENCES businesses(id), account_id TEXT NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS customers (id TEXT PRIMARY KEY, business_id TEXT NOT NULL REFERENCES businesses(id), phone TEXT NOT NULL, data_json TEXT NOT NULL DEFAULT '{}', updated_at INTEGER NOT NULL, UNIQUE(business_id, phone));
CREATE TABLE IF NOT EXISTS conversations (id TEXT PRIMARY KEY, business_id TEXT NOT NULL REFERENCES businesses(id), customer_id TEXT, status TEXT, data_json TEXT NOT NULL DEFAULT '{}', updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY, business_id TEXT NOT NULL REFERENCES businesses(id), conversation_id TEXT, message_id TEXT, direction TEXT, data_json TEXT NOT NULL DEFAULT '{}', updated_at INTEGER NOT NULL, UNIQUE(business_id, message_id));
CREATE TABLE IF NOT EXISTS message_delivery_events (id TEXT PRIMARY KEY, business_id TEXT NOT NULL REFERENCES businesses(id), message_id TEXT NOT NULL, status TEXT NOT NULL, data_json TEXT NOT NULL DEFAULT '{}', updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS automations (id TEXT PRIMARY KEY, business_id TEXT NOT NULL REFERENCES businesses(id), product TEXT NOT NULL CHECK(product IN ('eats','motos','cabs')), status TEXT NOT NULL, data_json TEXT NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS automation_events (id TEXT PRIMARY KEY, business_id TEXT NOT NULL REFERENCES businesses(id), status TEXT NOT NULL, data_json TEXT NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS automation_runs (id TEXT PRIMARY KEY, business_id TEXT NOT NULL REFERENCES businesses(id), automation_id TEXT NOT NULL, status TEXT NOT NULL, data_json TEXT NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS templates (id TEXT PRIMARY KEY, business_id TEXT NOT NULL REFERENCES businesses(id), product TEXT, status TEXT, data_json TEXT NOT NULL DEFAULT '{}', updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS campaigns (id TEXT PRIMARY KEY, business_id TEXT NOT NULL REFERENCES businesses(id), status TEXT, data_json TEXT NOT NULL DEFAULT '{}', updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS entitlements (business_id TEXT PRIMARY KEY REFERENCES businesses(id), whatsapp_automation INTEGER NOT NULL DEFAULT 0, campaigns INTEGER NOT NULL DEFAULT 0, advanced_analytics INTEGER NOT NULL DEFAULT 0, ai_assistant INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS subscriptions (business_id TEXT PRIMARY KEY REFERENCES businesses(id), plan TEXT NOT NULL, status TEXT NOT NULL, started_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, data_json TEXT NOT NULL DEFAULT '{}', updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS dashboard_handoffs (id TEXT PRIMARY KEY, business_id TEXT NOT NULL REFERENCES businesses(id), expires_at INTEGER NOT NULL, used_at INTEGER, data_json TEXT NOT NULL DEFAULT '{}', updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_conversations_business ON conversations(business_id, updated_at); CREATE INDEX IF NOT EXISTS idx_messages_business ON messages(business_id, updated_at); CREATE INDEX IF NOT EXISTS idx_automations_business ON automations(business_id, status); CREATE INDEX IF NOT EXISTS idx_runs_business ON automation_runs(business_id, status);
